import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_min_reduce(torch::Tensor x, int64_t dim);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cfloat>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void min_reduce_kernel(
    float const* __restrict__ in_ptr,
    float* __restrict__ out_ptr,
    int B, int D1, int D2,
    int dim)
{
    int out0, out1;
    if (dim == 0)      { out0 = D1; out1 = D2; }
    else if (dim == 1) { out0 = B;  out1 = D2; }
    else               { out0 = B;  out1 = D1; }
    int reduce_size = (dim == 0) ? B : (dim == 1) ? D1 : D2;
    // Precompute strides for direct pointer arithmetic, avoiding any
    // per-iteration branching / CUTE layout indirection inside the hot loop.
    long stride_i0, stride_i1, stride_k;
    if (dim == 0) {
        stride_i0 = D2;              // i0 -> D1 index
        stride_i1 = 1;               // i1 -> D2 index
        stride_k  = (long)D1 * D2;   // k  -> B  index
    } else if (dim == 1) {
        stride_i0 = (long)D1 * D2;   // i0 -> B  index
        stride_i1 = 1;               // i1 -> D2 index
        stride_k  = D2;              // k  -> D1 index
    } else {
        stride_i0 = (long)D1 * D2;   // i0 -> B  index
        stride_i1 = D2;              // i1 -> D1 index
        stride_k  = 1;               // k  -> D2 index
    }
    long total = (long)out0 * (long)out1;
    long idx = (long)blockIdx.x * blockDim.x + threadIdx.x;
    long grid_stride = (long)gridDim.x * blockDim.x;
    for (; idx < total; idx += grid_stride) {
        long i0 = idx / out1;
        long i1 = idx - i0 * out1;
        const float* __restrict__ base = in_ptr + i0 * stride_i0 + i1 * stride_i1;
        float m0 = FLT_MAX, m1 = FLT_MAX, m2 = FLT_MAX, m3 = FLT_MAX;
        float m4 = FLT_MAX, m5 = FLT_MAX, m6 = FLT_MAX, m7 = FLT_MAX;
        int k = 0;
        int limit8 = reduce_size - (reduce_size & 7);
        #pragma unroll 8
        for (; k < limit8; k += 8) {
            float v0 = base[(long)(k + 0) * stride_k];
            float v1 = base[(long)(k + 1) * stride_k];
            float v2 = base[(long)(k + 2) * stride_k];
            float v3 = base[(long)(k + 3) * stride_k];
            float v4 = base[(long)(k + 4) * stride_k];
            float v5 = base[(long)(k + 5) * stride_k];
            float v6 = base[(long)(k + 6) * stride_k];
            float v7 = base[(long)(k + 7) * stride_k];
            m0 = v0 < m0 ? v0 : m0;
            m1 = v1 < m1 ? v1 : m1;
            m2 = v2 < m2 ? v2 : m2;
            m3 = v3 < m3 ? v3 : m3;
            m4 = v4 < m4 ? v4 : m4;
            m5 = v5 < m5 ? v5 : m5;
            m6 = v6 < m6 ? v6 : m6;
            m7 = v7 < m7 ? v7 : m7;
        }
        for (; k < reduce_size; ++k) {
            float v = base[(long)k * stride_k];
            m0 = v < m0 ? v : m0;
        }
        float m = fminf(fminf(fminf(m0, m1), fminf(m2, m3)), fminf(fminf(m4, m5), fminf(m6, m7)));
        out_ptr[idx] = m;
    }
}
// Vectorized variant used when the "i1" (inner output) dimension has unit
// stride in the input tensor and the row stride (stride_i0) is 16-byte
// aligned. This lets us issue float4 loads that gather 4 consecutive output
// columns' worth of data with a single instruction, cutting instruction
// count roughly 4x while keeping the exact same coalesced access pattern.
__global__ void min_reduce_kernel_vec4(
    float const* __restrict__ in_ptr,
    float* __restrict__ out_ptr,
    int out0, int out1, int reduce_size,
    long stride_i0, long stride_k)
{
    int vec_out1 = out1 >> 2;
    int rem = out1 - (vec_out1 << 2);
    long total_vec = (long)out0 * (long)vec_out1;
    long total_rem = (long)out0 * (long)rem;
    long total = total_vec + total_rem;
    long idx = (long)blockIdx.x * blockDim.x + threadIdx.x;
    long grid_stride = (long)gridDim.x * blockDim.x;
    for (; idx < total; idx += grid_stride) {
        if (idx < total_vec) {
            long i0 = idx / vec_out1;
            long g  = idx - i0 * (long)vec_out1;
            long i1 = g * 4;
            const float* __restrict__ base = in_ptr + i0 * stride_i0 + i1;
            float m0 = FLT_MAX, m1 = FLT_MAX, m2 = FLT_MAX, m3 = FLT_MAX;
            for (int k = 0; k < reduce_size; ++k) {
                const float4 v = *reinterpret_cast<const float4*>(base + (long)k * stride_k);
                m0 = v.x < m0 ? v.x : m0;
                m1 = v.y < m1 ? v.y : m1;
                m2 = v.z < m2 ? v.z : m2;
                m3 = v.w < m3 ? v.w : m3;
            }
            float* out_base = out_ptr + i0 * (long)out1 + i1;
            out_base[0] = m0;
            out_base[1] = m1;
            out_base[2] = m2;
            out_base[3] = m3;
        } else {
            long ridx = idx - total_vec;
            long i0 = ridx / rem;
            long j  = ridx - i0 * (long)rem;
            long i1 = (long)vec_out1 * 4 + j;
            const float* __restrict__ base = in_ptr + i0 * stride_i0 + i1;
            float m = FLT_MAX;
            for (int k = 0; k < reduce_size; ++k) {
                float v = base[(long)k * stride_k];
                m = v < m ? v : m;
            }
            out_ptr[i0 * (long)out1 + i1] = m;
        }
    }
}
torch::Tensor cute_min_reduce(torch::Tensor x, int64_t dim) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 3, "x must be a 3D tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "expect float32 tensor");
    int d = (int)dim;
    if (d < 0) d += 3;
    TORCH_CHECK(d >= 0 && d < 3, "dim out of range");
    auto x_c = x.contiguous();
    int B  = (int)x_c.size(0);
    int D1 = (int)x_c.size(1);
    int D2 = (int)x_c.size(2);
    int out0, out1;
    if (d == 0)      { out0 = D1; out1 = D2; }
    else if (d == 1) { out0 = B;  out1 = D2; }
    else             { out0 = B;  out1 = D1; }
    auto out = torch::empty({out0, out1}, x_c.options());
    long total = (long)out0 * (long)out1;
    int threads = 256;
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    long stride_i0, stride_i1, stride_k;
    if (d == 0) {
        stride_i0 = D2;
        stride_i1 = 1;
        stride_k  = (long)D1 * D2;
    } else if (d == 1) {
        stride_i0 = (long)D1 * D2;
        stride_i1 = 1;
        stride_k  = D2;
    } else {
        stride_i0 = (long)D1 * D2;
        stride_i1 = D2;
        stride_k  = 1;
    }
    bool can_vec4 = (stride_i1 == 1) && (out1 >= 4) &&
                    ((stride_i0 % 4) == 0) &&
                    ((stride_k % 4) == 0) &&
                    (reinterpret_cast<uintptr_t>(x_c.data_ptr<float>()) % 16 == 0);
    long blocks = (total + threads - 1) / threads;
    if (can_vec4) {
        int reduce_size = (d == 0) ? B : (d == 1) ? D1 : D2;
        min_reduce_kernel_vec4<<<(unsigned int)blocks, threads, 0, stream>>>(
            x_c.data_ptr<float>(), out.data_ptr<float>(), out0, out1, reduce_size,
            stride_i0, stride_k);
    } else {
        min_reduce_kernel<<<(unsigned int)blocks, threads, 0, stream>>>(
            x_c.data_ptr<float>(), out.data_ptr<float>(), B, D1, D2, d);
    }
    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE min_reduce launch failed");
    return out;
}
"""

cute_ext = load_inline(
    name="cute_min_reduce_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_min_reduce"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Model that performs min reduction over a specific dimension using a custom CUTE kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_min_reduce(x, self.dim)

